static String classify(byte[] header) {
    if (header.length >= 2 && header[0] == 0x50 && header[1] == 0x4B) return "ZIP-like";
    if (header.length >= 4 && header[0] == (byte) 0x89 && header[1] == 0x50) return "PNG-like";
    return "UNKNOWN";
}

