static int readIntAt(Path plik, int index) throws IOException {
    try (BufferedInputStream in = new BufferedInputStream(new FileInputStream(plik.toFile()))) {
        in.skip((long) index * 4);
        return (in.read() << 24) | (in.read() << 16) | (in.read() << 8) | in.read();
    }
}

static int binarySearch(Path plik, int size, int target) throws IOException {
    int lo = 0, hi = size - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int value = readIntAt(plik, mid);
        if (value == target) return mid;
        if (value < target) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}

