        byte[] nameBytes = new byte[nameLen];
        in.read(nameBytes);
        String name = new String(nameBytes, StandardCharsets.UTF_8);

        int contentLen = (in.read() << 24) | (in.read() << 16) | (in.read() << 8) | in.read();
        byte[] content = new byte[contentLen];
        in.read(content);

        Files.write(restoreDir.resolve(name), content);
    }
}

for (Path f : sourceFiles) {
    Path restored = restoreDir.resolve(f.getFileName());
    System.out.println(f.getFileName() + " zgodny: " + (Files.mismatch(f, restored) == -1));
}
